// DocumentServiceHandler is an implementation of the opendesigner.v1.DocumentService service.
type DocumentServiceHandler interface {
	RenderBoard(context.Context, *connect.Request[v1.RenderBoardRequest]) (*connect.Response[v1.RenderBoardResponse], error)
	ReviewDesign(context.Context, *connect.Request[v1.ReviewDesignRequest]) (*connect.Response[v1.ReviewDesignResponse], error)
	// Compare changes: a frame marked ready for dev against its state when it was marked.
	CompareReady(context.Context, *connect.Request[v1.CompareReadyRequest]) (*connect.Response[v1.CompareReadyResponse], error)
	CreateVersion(context.Context, *connect.Request[v1.CreateVersionRequest]) (*connect.Response[v1.VersionInfo], error)
	ListVersions(context.Context, *connect.Request[v1.ListVersionsRequest]) (*connect.Response[v1.ListVersionsResponse], error)
	DeleteVersion(context.Context, *connect.Request[v1.DeleteVersionRequest]) (*connect.Response[v1.DeleteVersionResponse], error)
	// Opens a version (or the current state) as a NEW document: a branch to edit without touching the original.
	BranchDocument(context.Context, *connect.Request[v1.BranchRequest]) (*connect.Response[v1.DocInfo], error)
	// Access control (see AccessLink). Managing it needs an owner link, loopback, or the server's admin token.
	GetAccess(context.Context, *connect.Request[v1.GetAccessRequest]) (*connect.Response[v1.GetAccessResponse], error)
	EnableAccess(context.Context, *connect.Request[v1.EnableAccessRequest]) (*connect.Response[v1.EnableAccessResponse], error)
	DisableAccess(context.Context, *connect.Request[v1.DisableAccessRequest]) (*connect.Response[v1.DisableAccessResponse], error)
	CreateShareLink(context.Context, *connect.Request[v1.CreateShareLinkRequest]) (*connect.Response[v1.CreateShareLinkResponse], error)
	RevokeShareLink(context.Context, *connect.Request[v1.RevokeShareLinkRequest]) (*connect.Response[v1.RevokeShareLinkResponse], error)
	// Reads a Figma .fig file into nodes (experimental).
	ImportFig(context.Context, *connect.Request[v1.ImportFigRequest]) (*connect.Response[v1.ImportFigResponse], error)
	// Whether a document is a branch, and of what.
	GetBranchOrigin(context.Context, *connect.Request[v1.GetBranchOriginRequest]) (*connect.Response[v1.GetBranchOriginResponse], error)
	// What merging a branch back into its original would change, conflicts included.
	ReviewMerge(context.Context, *connect.Request[v1.ReviewMergeRequest]) (*connect.Response[v1.ReviewMergeResponse], error)
	// Merges a branch back into its original (as ordinary ops there, all or nothing).
	MergeBranch(context.Context, *connect.Request[v1.MergeBranchRequest]) (*connect.Response[v1.MergeBranchResponse], error)
	ListDocuments(context.Context, *connect.Request[v1.ListDocumentsRequest]) (*connect.Response[v1.ListDocumentsResponse], error)
	CreateDocument(context.Context, *connect.Request[v1.CreateDocumentRequest]) (*connect.Response[v1.DocInfo], error)
	// Renames a document (meta.json + the hub's in-memory name).
	RenameDocument(context.Context, *connect.Request[v1.RenameDocumentRequest]) (*connect.Response[v1.DocInfo], error)
	// Deletes a document by MOVING the bundle to <workspace>/.trash (never rm -rf).
	DeleteDocument(context.Context, *connect.Request[v1.DeleteDocumentRequest]) (*connect.Response[v1.DeleteDocumentResponse], error)
	OpenDocument(context.Context, *connect.Request[v1.OpenRequest]) (*connect.Response[v1.OpenResponse], error)
	// Submits an operation. The broadcast to all clients goes through Subscribe.
	SubmitOp(context.Context, *connect.Request[v1.SubmitOpRequest]) (*connect.Response[v1.SubmitOpResponse], error)
	// Stream of the applied OpRecords: catch-up from since_seq, then live.
	Subscribe(context.Context, *connect.Request[v1.SubscribeRequest], *connect.ServerStream[v1.ServerMsg]) error
	// Presence: the stream first sends the list of who is already there, then the
	// updates. Closing it = leaving the document.
	WatchPresence(context.Context, *connect.Request[v1.WatchPresenceRequest], *connect.ServerStream[v1.PresenceEvent]) error
	// Updates the client's cursor/selection (which must have an open stream).
	UpdatePresence(context.Context, *connect.Request[v1.UpdatePresenceRequest]) (*connect.Response[v1.UpdatePresenceResponse], error)
	// Editor jobs (see EditorJob): the editor watches, an agent runs, the editor completes.
	WatchJobs(context.Context, *connect.Request[v1.WatchJobsRequest], *connect.ServerStream[v1.EditorJob]) error
	RunJob(context.Context, *connect.Request[v1.RunJobRequest]) (*connect.Response[v1.RunJobResponse], error)
	CompleteJob(context.Context, *connect.Request[v1.CompleteJobRequest]) (*connect.Response[v1.CompleteJobResponse], error)
	// Flow analysis (screen graph): unreachable screens, dead ends, paths.
	// Computed by the server (internal/flow), so UI, CLI and MCP agents see the
	// same result.
	AnalyzeFlows(context.Context, *connect.Request[v1.AnalyzeFlowsRequest]) (*connect.Response[v1.AnalyzeFlowsResponse], error)
	// Exports the design as code (internal/codegen): the list of files of the
	// generated project, computed from the current snapshot. As with
	// AnalyzeFlows, CLI, MCP and editor see the same result.
	ExportCode(context.Context, *connect.Request[v1.ExportCodeRequest]) (*connect.Response[v1.ExportCodeResponse], error)
	// Draws a diagram (flowchart, UML classes, UML sequence, UML states) from
	// Mermaid text. Pure and stateless: see RenderDiagramRequest.
	RenderDiagram(context.Context, *connect.Request[v1.RenderDiagramRequest]) (*connect.Response[v1.RenderDiagramResponse], error)
}

